document.addEventListener('click',e=>{const zone=e.target.closest('.dropzone');if(zone&&!e.target.closest('[data-action]'))chooseUpload(zone.dataset.dropId)});
document.addEventListener('keydown',e=>{const z=e.target.closest('.dropzone');if(z&&(e.key==='Enter'||e.key===' ')){e.preventDefault();chooseUpload(z.dataset.dropId)}});
document.addEventListener('dragover',e=>{const z=e.target.closest('[data-drop-id]');if(z){e.preventDefault();e.dataTransfer.dropEffect='copy';z.classList.add('dragover')}});
document.addEventListener('dragleave',e=>{const z=e.target.closest('[data-drop-id]');if(z&&!z.contains(e.relatedTarget))z.classList.remove('dragover')});
document.addEventListener('drop',e=>{const z=e.target.closest('[data-drop-id]');if(z){e.preventDefault();z.classList.remove('dragover');const file=Array.from(e.dataTransfer.files||[]).find(f=>f.type.startsWith('image/'))||Array.from(e.dataTransfer.items||[]).filter(i=>i.kind==='file').map(i=>i.getAsFile()).find(f=>f?.type.startsWith('image/'));if(file)handleImage(file,z.dataset.dropId);else toast('Enregistre l’image de ChatGPT, puis glisse son fichier ici.',true)}});
